'use strict';
const icons={home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 4v2"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18M15 13h6M16 16h1"/>',check:'<rect x="4" y="3" width="16" height="19" rx="2"/><path d="m8 12 3 3 5-6M8 3v3h8V3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18M8 14h2M14 14h2M8 18h2"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',alert:'<path d="m12 3 10 18H2L12 3Z M12 9v5M12 17h.01"/>',file:'<path d="M14 2H4v20h16V8l-6-6ZM14 2v6h6M8 13h8M8 17h6"/>',ball:'<circle cx="12" cy="12" r="9"/><path d="m12 7 5 4-2 6H9l-2-6 5-4ZM12 7V3M17 11l4-2M15 17l3 3M9 17l-3 3M7 11 3 9"/>',eye:'<path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.file}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(n);
let state=null,view=(location.hash||'#inicio').slice(1),selectedCategory='Todas',selectedStatus='Todos',query='',weekStart=monday(today()),chosenSession=null,sessionData=null,renderToken=0;
const main=document.querySelector('#main'),modal=document.querySelector('#modal');
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Bogota',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function monday(d){const day=new Date(d+'T12:00:00Z').getUTCDay();return isoAdd(d,-((day+6)%7))}
const dateText=d=>d?d.split('-').reverse().join('/'):'—';
const initials=n=>n.split(' ').slice(0,2).map(x=>x[0]).join('');
const admin=()=>state?.member.role==='admin';
function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),4500)}
function title(k,t,s,buttons=''){return `<div class="page-head"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p class="sub">${s}</p></div><div class="actions">${buttons}</div></div>`}
function button(t,fn,primary=false,ic=''){return `<button class="btn ${primary?'primary':''}" onclick="${fn}">${ic?icon(ic):''}${t}</button>`}
function stat(t,v,n,i){return `<article class="stat"><div class="stat-top">${t}${icon(i)}</div><strong>${v}</strong><small>${n}</small></article>`}
function athleteAvatar(p,large=false){return p.photo_key?`<span class="avatar athlete-photo ${large?'large':''}"><img src="/api/photos/${encodeURIComponent(p.id)}?v=${encodeURIComponent(p.updated_at||'')}" alt="Foto de ${esc(p.name)}" loading="lazy" onerror="this.parentElement.textContent='${esc(initials(p.name))}'"></span>`:`<span class="avatar ${large?'large':''}">${esc(initials(p.name))}</span>`}
function staffAvatar(large=false){const n=esc(initials(state.member.name));return `<span class="avatar staff-avatar ${large?'large':''}"><span class="staff-avatar-fallback">${n}</span><img src="/api/staff-photo?v=${encodeURIComponent(state.member.photoVersion||0)}" alt="Fotografía de ${esc(state.member.name)}" onload="this.parentElement.classList.add('loaded')" onerror="this.remove()"></span>`;}
let staffCameraStream=null;
async function openStaffCamera(){
 const video=document.querySelector('#staff-camera-video'),panel=document.querySelector('#staff-camera-panel');
 if(!video||!panel)return;
 if(!navigator.mediaDevices?.getUserMedia){toast('Este navegador no permite utilizar la cámara.');return}
 try{
  staffCameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});
  panel.hidden=false;video.srcObject=staffCameraStream;await video.play();
 }catch{toast('No se pudo activar la cámara. Revisa los permisos del navegador.')}
}
function closeStaffCamera(){
 if(staffCameraStream){staffCameraStream.getTracks().forEach(t=>t.stop());staffCameraStream=null}
 const video=document.querySelector('#staff-camera-video'),panel=document.querySelector('#staff-camera-panel');
 if(video)video.srcObject=null;if(panel)panel.hidden=true;
}
async function captureStaffCamera(){
 const video=document.querySelector('#staff-camera-video');
 if(!video||!video.videoWidth){toast('Espera a que la cámara esté lista.');return}
 const canvas=document.createElement('canvas'),max=1000,scale=Math.min(1,max/Math.max(video.videoWidth,video.videoHeight));
 canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);
 canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);
 const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',0.82));
 if(!blob){toast('No se pudo capturar la fotografía.');return}
 const file=new File([blob],'foto-perfil.jpg',{type:'image/jpeg'});
 closeStaffCamera();await saveStaffPhotoFile(file);
}
async function saveStaffPhoto(input){const file=input?.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>2*1024*1024){toast('Selecciona una imagen JPG, PNG o WebP de máximo 2 MB.');input.value='';return;}await saveStaffPhotoFile(file);input.value='';}
async function saveStaffPhotoFile(file){const fd=new FormData();fd.append('photo',file);try{const r=await fetch('/api/staff-photo',{method:'POST',credentials:'same-origin',body:fd});const data=await r.json();if(!r.ok)throw Error(data.error||'No se pudo guardar la fotografía.');state.member.photoVersion=Date.now();render();toast('Fotografía guardada en Cloudflare R2.');}catch(e){toast(e.message||'Error al guardar fotografía.')}}
function person(p){return `<div class="person">${athleteAvatar(p)}<div><strong>${esc(p.name)}</strong><small>${esc(p.category)}</small></div></div>`}
function errorBox(msg){return `<div class="notice" role="alert">${esc(msg)}</div>`}
async function api(path,method='GET',body){let res;try{res=await fetch('/api/'+path,{method,credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined})}catch{throw Error('No hay conexión. Conserva esta ventana y vuelve a intentar guardar.')}let data;try{data=await res.json()}catch{throw Error('No se pudo confirmar la operación. Revisa la conexión e inténtalo de nuevo.')}if(!res.ok)throw Error(data.error||'No se pudo completar la operación');return data;}
async function uploadAthletePhoto(id,file){const fd=new FormData();fd.append('photo',file);const res=await fetch('/api/photos/'+encodeURIComponent(id),{method:'POST',credentials:'same-origin',body:fd});let data={};try{data=await res.json()}catch{}if(!res.ok)throw Error(data.error||'No se pudo guardar la foto.');return data}
async function removeAthletePhoto(id){const res=await fetch('/api/photos/'+encodeURIComponent(id),{method:'DELETE',credentials:'same-origin'});let data={};try{data=await res.json()}catch{}if(!res.ok)throw Error(data.error||'No se pudo eliminar la foto.');return data}
async function refresh(){state=await api('bootstrap')}
function currentSchedule(){return occurrences(weekStart,isoAdd(weekStart,6)).filter(s=>state.schedule.some(ss=>ss.id===s.id)).map(s=>({...s,key:s.date+'_'+s.category}))}
function go(v,preserveFilters=false){view=v;location.hash=v;if(!preserveFilters){selectedCategory='Todas';selectedStatus='Todos';query='';}document.querySelector('#sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'})}
function render(){const nav=[['inicio','Resumen','home'],['deportistas',admin()?'Deportistas':'Mis deportistas','users'],['asistencia','Asistencia','check'],['sesiones','Entrenamientos','calendar'],['equipo','Equipo y categorías','users'],['cuenta','Mi cuenta','users'],...(state.member.owner?[['accesos','Accesos','check']]:[]),...(admin()?[['finanzas','Pagos y cartera','wallet'],['contabilidad','Contabilidad','file'],['historial','Actividad','clock']]:[])];document.querySelector('#nav').innerHTML=nav.map(([v,t,i])=>`<button class="${view===v?'active':''}" onclick="go('${v}')">${icon(i)}${t}</button>`).join('');document.querySelector('#crumb').textContent=nav.find(n=>n[0]===view)?.[1]||'Mi club';document.querySelector('.user').innerHTML=`${staffAvatar()}<div>${esc(state.member.name)}<small>${esc(state.member.title)}</small></div>`;main.innerHTML=({inicio:home,deportistas:roster,asistencia:attendancePage,sesiones:agenda,equipo:team,cuenta:accountPage,accesos:accessPage,historial:auditPage,finanzas:financePage,contabilidad:accountingPage}[view]||home)();if(view==='cuenta')bindAccountForm();}
function home(){return title('BASE DEL CLUB','Tu club, conectado.','Las fichas y la asistencia se guardan en la base compartida.',admin()?button('Registrar deportista','athleteForm()',true,'plus'):'')+`<div class="stats">${stat('Deportistas registrados',state.athletes.filter(p=>p.status!=='inactive').length,'Activos e incompletos','users')}${stat('Categorías',state.categories.length,'Con horarios configurados','ball')}${stat('Sesiones de la semana',currentSchedule().length,'Según el horario habitual','calendar')}<article class="stat staff-access-stat"><div class="stat-top">Acceso${icon('check')}</div><div class="staff-access-content">${staffAvatar()}<div><strong>${admin()?'Administrativo':'Entrenador'}</strong><small>${esc(state.member.name)}</small></div></div></article></div><div class="dashboard-grid"><div><section class="card"><div class="card-head"><h2>Para comenzar</h2></div><div class="info-row">${icon('users')}<div><strong>Fichas de deportistas</strong><small>Acudiente, emergencias y seguimiento físico</small></div><button class="btn link" onclick="go('deportistas')">Abrir</button></div><div class="info-row">${icon('check')}<div><strong>Asistencia por sesión</strong><small>Una lista compartida por los profesores asignados</small></div><button class="btn link" onclick="go('asistencia')">Tomar lista</button></div><div class="info-row">${icon('calendar')}<div><strong>Agenda del club</strong><small>Horarios y canchas que ya definimos</small></div><button class="btn link" onclick="go('sesiones')">Consultar</button></div></section></div><div><section class="card"><div class="card-head"><h2>Esta primera etapa</h2></div><div class="training-inner"><p class="sub">Ya puedes guardar fichas, editar sus datos, registrar mediciones y tomar asistencia.</p><div class="notice neutral" style="margin-top:18px">Pagos y cartera disponibles desde octubre de 2026. Primero revisa y activa cada cuenta. Los archivos y el envío de correos siguen pendientes.</div>${admin()?button('Pagos y cartera',"go('finanzas')"):''}</div></section></div></div>`}
function visiblePlayers(){return state.athletes.filter(p=>(selectedCategory==='Todas'||p.category===selectedCategory)&&(selectedStatus==='Todos'||(selectedStatus==='Incompletos'?p.status==='incomplete':p.status!=='incomplete'))&&p.name.toLowerCase().includes(query.toLowerCase()))}
function roster(){return title('DEPORTISTAS','Fichas del club.','Datos del acudiente, contacto de emergencia e historial físico.',admin()?button('Registrar deportista','athleteForm()',true,'plus'):'')+`<div class="toolbar"><label class="search">${icon('search')}<input aria-label="Buscar deportista" placeholder="Buscar por nombre…" value="${esc(query)}" oninput="query=this.value;document.querySelector('#roster').innerHTML=rosterTable()"></label><select class="filter" aria-label="Estado de ficha" onchange="selectedStatus=this.value;document.querySelector('#roster').innerHTML=rosterTable()"><option value="Todos" ${selectedStatus==='Todos'?'selected':''}>Todos</option><option value="Incompletos" ${selectedStatus==='Incompletos'?'selected':''}>Solo incompletos</option><option value="Completos" ${selectedStatus==='Completos'?'selected':''}>Solo completos</option></select><select class="filter" aria-label="Categoría" onchange="selectedCategory=this.value;document.querySelector('#roster').innerHTML=rosterTable()"><option ${selectedCategory==='Todas'?'selected':''}>Todas</option>${state.categories.map(c=>`<option ${selectedCategory===c?'selected':''}>${c}</option>`).join('')}</select></div><section class="card" id="roster">${rosterTable()}</section>`}
function eligibilityBadge(p){if(p.status==='incomplete')return '<span class="badge warn">Registro incompleto</span>';const e=p.eligibility;return e?`<span class="badge ${e.status==='restricted'?'danger':e.status==='eligible'||e.status==='exception'?'ok':'warn'}">${esc(e.label)}</span>`:''}
function rosterTable(){const ps=visiblePlayers();return ps.length?`<div class="table-wrap roster-wrap"><table class="roster-table"><thead><tr><th>Deportista</th><th>Acudiente</th><th>Modalidad y estado</th><th>Ficha</th></tr></thead><tbody>${ps.map(p=>`<tr><td>${person(p)}${p.internal_note?'<br><span class="badge warn">Nota interna</span>':''}</td><td>${p.status==='incomplete'?'<span class="muted">Pendiente de completar</span>':esc(p.guardian)+'<br><span class="muted">'+esc(p.phone)+'</span>'}</td><td>${esc(p.modality)}<br>${eligibilityBadge(p)}</td><td><button class="btn link" onclick="profile('${p.id}')">Ver ficha</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No hay deportistas registrados con estos filtros.<br>'+ (admin()?'Usa “Registrar deportista” para crear la primera ficha.':'El administrador debe cargar las fichas de tu categoría.')+'</div>'}
function showModal(t,b){document.querySelector('#modal-content').innerHTML=`<div class="modal-head"><h2>${t}</h2><button class="icon-btn" onclick="modal.close()" aria-label="Cerrar">×</button></div><div class="modal-body">${b}</div>`;if(!modal.open)modal.showModal()}
function field(label,name,value='',type='text',required=true,full=false,max=150){return `<label class="field ${full?'full':''}">${label}<input name="${name}" value="${esc(value)}" type="${type}" ${required?'required':''} maxlength="${max}"></label>`}
function togglePasswordInput(btn){const input=btn.parentElement?.querySelector('input');if(!input)return;const show=input.type==='password';input.type=show?'text':'password';btn.setAttribute('aria-label',show?'Ocultar contraseña':'Mostrar contraseña');btn.innerHTML=show?'×':icon('eye');}
function athleteForm(id){if(!admin())return;const p=state.athletes.find(p=>p.id===id)||{};const incomplete=p.status==='incomplete';const token=crypto.randomUUID();showModal(incomplete?'Completar ficha':id?'Editar ficha':'Registrar deportista',`${incomplete?'<div class="notice neutral">Ya cargamos los datos del deportista. Completa solamente la información familiar, modalidad y autorización que falte. El contacto de emergencia adicional es opcional.</div>':'<p class="sub" style="margin-bottom:20px">Esta ficha se guardará en la base del club. El registro no genera cobros ni confirma pagos.</p>'}<form id="athlete-form"><div class="form-grid">${field('Nombre completo','name',p.name,'text',true,true,100)}${field('Fecha de nacimiento','dob',p.dob,'date')}<label class="field">Categoría<select name="category">${[...CLUB.categories,...(p.category==='Por definir'?['Por definir']:[])].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Tipo de documento<select name="docType"><option value="">Pendiente</option>${['Registro civil','Tarjeta de identidad','PPT','Cédula','Otro'].map(t=>`<option ${p.doc_type===t?'selected':''}>${t}</option>`).join('')}</select></label>${field('Número de documento (opcional)','docNumber',p.doc_number,'text',false,false,40)}${field('Dirección y municipio (opcional)','address',p.address,'text',false,true,250)}<div class="section-title full-width">ACUDIENTE PRINCIPAL</div>${field('Nombre del acudiente','guardian',p.guardian,'text',true,true,100)}${field('Parentesco','relationship',p.relationship,'text',true,false,50)}${field('Celular','phone',p.phone,'tel',true,false,30)}${field('Correo (opcional)','email',p.email,'email',false,true,254)}<div class="section-title full-width">CONTACTO DE EMERGENCIA ADICIONAL (OPCIONAL)</div>${field('Nombre del contacto','emergencyName',p.emergency_name,'text',false,true,100)}${field('Relación con el niño','emergencyRelation',p.emergency_relation,'text',false,false,50)}${field('Celular de emergencia','emergencyPhone',p.emergency_phone,'tel',false,false,30)}<label class="field full">Información relevante para la práctica (opcional)<textarea name="healthNotes" maxlength="1500" rows="3">${esc(p.health_notes||'')}</textarea></label><label class="field">Modalidad<input name="modality" value="Mensual" readonly></label>${field('Fecha de autorización','consentDate',p.consent_date||today(),'date')}<label class="field full consent-check"><input name="consent" type="checkbox" required ${p.consent?'checked':''}>Confirmo que el club cuenta con la autorización del acudiente para registrar estos datos y la información de salud suministrada. Esta casilla no reemplaza el soporte de autorización.</label></div><div id="form-error" style="margin-top:15px"></div><div class="form-actions"><button type="button" class="btn" onclick="modal.close()">Cancelar</button><button class="btn primary" type="submit">${incomplete?'Completar y activar ficha':'Guardar ficha'}</button></div></form>`);document.querySelector('#athlete-form').onsubmit=async e=>{e.preventDefault();const form=e.target,submit=form.querySelector('[type=submit]');if(submit.disabled)return;submit.disabled=true;const d=Object.fromEntries(new FormData(form));d.consent=true;d.requestId=token;if(id)d.version=p.version;try{await api('athletes'+(id?'/'+id:''),id?'PUT':'POST',d);await refresh();modal.close();go('deportistas',true);toast('Ficha guardada en la base del club.')}catch(err){document.querySelector('#form-error').innerHTML=errorBox(err.message)}finally{submit.disabled=false}};}
async function profile(id){const p=state.athletes.find(p=>p.id===id);if(!p)return;showModal('Ficha del deportista',`${p.status==='incomplete'?'<div class="notice">Registro incompleto: faltan datos del acudiente, emergencia, modalidad y autorización. Completa la ficha para activarla.</div>':''}<div class="profile-head">${athleteAvatar(p,true)}<div><h2>${esc(p.name)}</h2><p class="sub">${p.category} · ${esc(p.modality||'Modalidad pendiente')}</p></div></div><div class="detail-grid"><div class="detail"><small>Nacimiento</small>${dateText(p.dob)}</div><div class="detail"><small>Última actualización</small>${new Date(p.updated_at).toLocaleString('es-CO',{timeZone:'America/Bogota'})}</div>${admin()?`<div class="detail"><small>Documento</small>${esc(p.doc_type||'Pendiente')} · ${esc(p.doc_number||'Sin registrar')}</div><div class="detail"><small>Dirección</small>${esc(p.address||'Sin registrar')}</div>`:''}</div><div class="section-title">ACUDIENTE</div><div class="detail-grid"><div class="detail"><small>${esc(p.relationship||'Acudiente')}</small>${esc(p.guardian||'Pendiente')}</div><div class="detail"><small>Celular</small>${p.phone?`<a href="tel:${esc(p.phone.replace(/[^+\d]/g,''))}">${esc(p.phone)}</a>`:'Pendiente'}</div>${admin()?`<div class="detail full-width"><small>Correo</small>${esc(p.email||'Sin correo registrado')}</div>`:''}</div><div class="section-title">EMERGENCIA</div><div class="detail-grid"><div class="detail"><small>${esc(p.emergency_relation||'Contacto de emergencia')}</small>${esc(p.emergency_name||'Pendiente')}</div><div class="detail"><small>Celular</small>${p.emergency_phone?`<a href="tel:${esc(p.emergency_phone.replace(/[^+\d]/g,''))}">${esc(p.emergency_phone)}</a>`:'Pendiente'}</div></div><div class="detail" style="margin-top:14px"><small>Información para la práctica</small>${esc(p.health_notes||'Sin información reportada')}</div><div class="section-title">NOTA INTERNA DEL CLUB</div><div class="detail"><small>Uso interno</small>${p.internal_note?esc(p.internal_note):'<span class="muted">Sin nota interna.</span>'}</div><div class="form-actions" style="justify-content:flex-start"><button class="btn" onclick="athleteNoteForm('${id}')">${p.internal_note?'Editar nota':'Agregar nota'}</button></div><div class="section-title">MEDICIONES</div><div id="measures">Cargando historial…</div><div class="form-actions">${admin()?`<button class="btn" onclick="athleteForm('${id}')">${p.status==='incomplete'?'Completar ficha':'Editar ficha'}</button><button class="btn" onclick="photoForm('${id}')">${p.photo_key?'Cambiar foto':'Agregar foto'}</button><button class="btn" onclick="changeAthleteStatus('${id}','${p.status==='inactive'?'active':'inactive'}')">${p.status==='inactive'?'Reactivar':'Desactivar'}</button><button class="btn danger" onclick="deleteAthlete('${id}')">Eliminar definitivamente</button>`:''}<button class="btn primary" onclick="measurementForm('${id}')">Nueva medición</button></div>`);try{const r=await api('athletes/'+id+'/measurements');const el=document.querySelector('#measures');if(!el)return;el.innerHTML=r.measurements.length?`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Peso</th><th>Estatura</th><th>IMC</th><th>Registró</th></tr></thead><tbody>${r.measurements.map(m=>`<tr><td>${dateText(m.date)}</td><td>${m.weight} kg</td><td>${m.height} cm</td><td>${m.bmi.toFixed(2)}</td><td>${esc(m.recorder)}</td></tr>`).join('')}</tbody></table></div><p class="muted">IMC numérico, sin clasificación clínica ni efecto en la habilitación.</p>`:'<p class="muted">Aún no se han registrado mediciones.</p>'}catch(err){const el=document.querySelector('#measures');if(el)el.innerHTML=errorBox(err.message)}}
let athleteCameraStream=null;
function photoForm(id){const p=state.athletes.find(p=>p.id===id);if(!p||!admin())return;stopAthleteCamera();showModal('Foto del deportista',`<div class="photo-manager"><div class="photo-preview large-preview">${p.photo_key?`<img src="/api/photos/${encodeURIComponent(id)}?v=${encodeURIComponent(p.updated_at||'')}" alt="Foto de ${esc(p.name)}">`:`<span>${esc(initials(p.name))}</span>`}</div><div><h3>${esc(p.name)}</h3><p class="muted">Puedes elegir una imagen o tomarla directamente con la cámara del computador. JPG, PNG o WebP. Máximo 5 MB.</p><input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp"><div class="form-actions" style="justify-content:flex-start"><button type="button" class="btn" onclick="startAthleteCamera('${id}')">Usar cámara</button></div><div id="athlete-camera" style="display:none;margin-top:14px"><video id="athlete-camera-video" autoplay playsinline muted style="width:100%;max-width:420px;border-radius:14px;background:#111"></video><canvas id="athlete-camera-canvas" style="display:none"></canvas><div class="form-actions" style="justify-content:flex-start"><button type="button" class="btn primary" onclick="captureAthletePhoto()">Tomar foto</button><button type="button" class="btn" onclick="stopAthleteCamera()">Cancelar cámara</button></div></div><div id="photo-error" style="margin-top:12px"></div><div class="form-actions"><button type="button" class="btn" onclick="stopAthleteCamera();profile('${id}')">Volver</button>${p.photo_key?`<button type="button" class="btn danger" onclick="deletePhoto('${id}')">Eliminar foto</button>`:''}<button type="button" class="btn primary" onclick="savePhoto('${id}')">Guardar foto</button></div></div></div>`);const input=document.querySelector('#photo-file');if(input)input.onchange=()=>{const file=input.files?.[0];if(!file)return;stopAthleteCamera();showAthletePhotoPreview(file)}}
function showAthletePhotoPreview(file){const box=document.querySelector('.large-preview');if(!box)return;box.innerHTML='';const img=document.createElement('img');img.alt='Vista previa';img.src=URL.createObjectURL(file);box.appendChild(img)}
async function startAthleteCamera(){const err=document.querySelector('#photo-error');if(!navigator.mediaDevices?.getUserMedia){if(err)err.innerHTML=errorBox('Este navegador no permite usar la cámara desde aquí.');return}try{stopAthleteCamera();athleteCameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});const wrap=document.querySelector('#athlete-camera'),video=document.querySelector('#athlete-camera-video');if(wrap)wrap.style.display='block';if(video){video.srcObject=athleteCameraStream;await video.play()}}catch(e){if(err)err.innerHTML=errorBox('No se pudo abrir la cámara. Revisa el permiso del navegador y vuelve a intentarlo.')}}
function captureAthletePhoto(){const video=document.querySelector('#athlete-camera-video'),canvas=document.querySelector('#athlete-camera-canvas'),input=document.querySelector('#photo-file'),err=document.querySelector('#photo-error');if(!video||!canvas||!input||!video.videoWidth||!video.videoHeight){if(err)err.innerHTML=errorBox('La cámara todavía no está lista. Espera un momento e inténtalo de nuevo.');return}canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>{if(!blob){if(err)err.innerHTML=errorBox('No se pudo capturar la foto.');return}const file=new File([blob],'foto-deportista-'+Date.now()+'.jpg',{type:'image/jpeg'});const dt=new DataTransfer();dt.items.add(file);input.files=dt.files;showAthletePhotoPreview(file);stopAthleteCamera();},'image/jpeg',0.92)}
function stopAthleteCamera(){if(athleteCameraStream){athleteCameraStream.getTracks().forEach(t=>t.stop());athleteCameraStream=null}const wrap=document.querySelector('#athlete-camera'),video=document.querySelector('#athlete-camera-video');if(video)video.srcObject=null;if(wrap)wrap.style.display='none'}
async function savePhoto(id){const input=document.querySelector('#photo-file'),file=input?.files?.[0],err=document.querySelector('#photo-error');if(!file){if(err)err.innerHTML=errorBox('Selecciona una foto.');return}if(file.size>5*1024*1024){if(err)err.innerHTML=errorBox('La foto debe pesar máximo 5 MB.');return}try{await uploadAthletePhoto(id,file);await refresh();await profile(id);toast('Foto guardada.')}catch(e){if(err)err.innerHTML=errorBox(e.message)}}
async function deletePhoto(id){if(!confirm('¿Eliminar la foto de este deportista?'))return;try{await removeAthletePhoto(id);await refresh();await profile(id);toast('Foto eliminada.')}catch(e){toast(e.message)}}
async function changeAthleteStatus(id,status){
 const p=state.athletes.find(p=>p.id===id);if(!p)return;
 const verb=status==='inactive'?'desactivar':'reactivar';
 if(!confirm('¿Seguro que deseas '+verb+' a '+p.name+'?'))return;
 try{
  await api('athletes/'+id+'/status','PUT',{status});
  await refresh();
  modal.close();
  go('deportistas',true);
  toast(status==='inactive'?'Deportista desactivado.':'Deportista reactivado.');
 }catch(e){toast(e.message)}
}
async function deleteAthlete(id){
 const p=state.athletes.find(p=>p.id===id);if(!p)return;
 const typed=prompt('Para eliminar definitivamente esta ficha escribe ELIMINAR.\n\nSolo se permitirá si no tiene historial, asistencia ni movimientos financieros.');
 if(typed!=='ELIMINAR')return;
 try{
  await api('athletes/'+id,'DELETE');
  await refresh();
  modal.close();
  go('deportistas',true);
  toast('Ficha eliminada definitivamente.');
 }catch(e){toast(e.message)}
}
function measurementForm(id){const p=state.athletes.find(p=>p.id===id);if(!p)return;const requestId=crypto.randomUUID();showModal('Nueva medición',`<p style="margin-bottom:20px">${esc(p.name)}</p><form id="measurement-form"><div class="form-grid">${field('Fecha de medición','date',today(),'date',true,true)}<label class="field">Peso (kg)<input name="weight" id="weight" type="number" min="1" max="300" step="0.1" required oninput="calcBMI()"></label><label class="field">Estatura (cm)<input name="height" id="height" type="number" min="40" max="250" step="0.1" required oninput="calcBMI()"></label></div><div class="bmi-result"><span>IMC · kg/m²</span><strong id="bmi">—</strong></div><p class="muted" style="margin-top:12px">El valor es un indicador de seguimiento. Su interpretación en niños requiere edad y sexo; esta etapa no emite clasificaciones.</p><div id="form-error"></div><div class="form-actions"><button type="button" class="btn" onclick="profile('${id}')">Volver</button><button class="btn primary" type="submit">Guardar medición</button></div></form>`);document.querySelector('#measurement-form').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('[type=submit]');if(submit.disabled)return;submit.disabled=true;const b=Object.fromEntries(new FormData(e.target));try{await api('athletes/'+id+'/measurements','POST',{requestId,date:b.date,weight:Number(b.weight),height:Number(b.height)});await profile(id);toast('Medición guardada en el historial.')}catch(err){document.querySelector('#form-error').innerHTML=errorBox(err.message);submit.disabled=false}};}
function calcBMI(){const w=Number(document.querySelector('#weight').value),h=Number(document.querySelector('#height').value);document.querySelector('#bmi').textContent=w>0&&h>=40?(w/(h/100)**2).toFixed(2):'—'}
let sessionHistory=[],sessionHistoryCategory='Todas',sessionHistoryMonth='';
function agenda(){const ss=currentSchedule();setTimeout(loadSessionHistory,0);return title('AGENDA DEL CLUB','Entrenamientos de la semana.',dateText(weekStart)+' al '+dateText(isoAdd(weekStart,6)),button('Semana anterior','moveWeek(-7)')+button('Semana siguiente','moveWeek(7)'))+(ss.length?ss.map(s=>`<section class="card"><div class="session-card"><div class="datebox"><span>${WEEKDAYS[s.day].slice(0,3).toUpperCase()}</span><strong>${s.date.slice(-2)}</strong></div><div class="session-content"><h3>${s.category}</h3><p>${s.start}–${s.end} · ${CLUB.venues[s.venue]}</p><p>${s.coaches.map(id=>coachById(id).name).join(' · ')}</p></div><div class="session-actions"><button class="btn primary" onclick="chooseSession('${s.key}')">Abrir sesión</button></div></div></section>`).join(''):'<section class="card"><div class="empty">No hay entrenamientos configurados para esta semana.</div></section>')+`<section class="card" style="margin-top:22px"><div class="card-head"><div><h2>Historial de entrenamientos</h2><p>Sesiones con asistencia, ejecución u observaciones guardadas.</p></div></div><div id="session-history"><div class="empty">Cargando historial…</div></div></section>`}

async function loadSessionHistory(){
 const el=document.querySelector('#session-history');if(!el)return;
 try{
  const r=await api('sessions/history');
  sessionHistory=r.sessions||[];
  if(!sessionHistoryMonth){
   const current=today().slice(0,7);
   sessionHistoryMonth=sessionHistory.some(s=>s.date?.startsWith(current))?current:'';
  }
  paintSessionHistory();
 }catch(e){el.innerHTML=errorBox(e.message)}
}
function sessionAttendanceSummary(s){
 let att={};try{att=JSON.parse(s.attendance_json||'{}')}catch{}
 const values=Object.values(att).map(v=>typeof v==='string'?v:v?.status);
 return {present:values.filter(v=>v==='presente').length,absent:values.filter(v=>v==='ausente').length,other:values.filter(v=>v&&v!=='presente'&&v!=='ausente').length,total:values.filter(Boolean).length};
}
function sessionStatusLabel(s){return {programada:'Programada',realizada:'Realizada',cancelada:'Cancelada'}[s]||s}
function paintSessionHistory(){
 const el=document.querySelector('#session-history');if(!el)return;
 const months=[...new Set(sessionHistory.map(s=>s.date?.slice(0,7)).filter(Boolean))].sort().reverse();
 const cats=[...new Set(sessionHistory.map(s=>s.category).filter(Boolean))].sort();
 const filtered=sessionHistory.filter(s=>(sessionHistoryCategory==='Todas'||s.category===sessionHistoryCategory)&&(!sessionHistoryMonth||s.date?.startsWith(sessionHistoryMonth)));
 el.innerHTML=`<div class="toolbar" style="padding:0 20px 16px">
  <select class="filter" aria-label="Filtrar historial por categoría" onchange="sessionHistoryCategory=this.value;paintSessionHistory()"><option ${sessionHistoryCategory==='Todas'?'selected':''}>Todas</option>${cats.map(c=>`<option ${sessionHistoryCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select>
  <select class="filter" aria-label="Filtrar historial por mes" onchange="sessionHistoryMonth=this.value;paintSessionHistory()"><option value="" ${!sessionHistoryMonth?'selected':''}>Todos los meses</option>${months.map(m=>`<option value="${m}" ${sessionHistoryMonth===m?'selected':''}>${new Date(m+'-01T12:00:00').toLocaleDateString('es-CO',{month:'long',year:'numeric'})}</option>`).join('')}</select>
 </div>
 ${filtered.length?`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Categoría</th><th>Estado</th><th>Asistencia</th><th>Observación</th><th>Detalle</th></tr></thead><tbody>${filtered.map(s=>{const a=sessionAttendanceSummary(s);return `<tr><td><strong>${dateText(s.date)}</strong></td><td>${esc(s.category)}</td><td><span class="badge ${s.status==='cancelada'?'danger':s.status==='realizada'?'ok':'blue'}">${esc(sessionStatusLabel(s.status))}</span></td><td>${s.attendance_saved?`<strong>${a.present} P</strong> · ${a.absent} A${a.other?' · '+a.other+' otros':''}`:'<span class="muted">Sin lista</span>'}</td><td>${s.notes?esc(s.notes.slice(0,90))+(s.notes.length>90?'…':''):'<span class="muted">Sin observación</span>'}</td><td><button class="btn link" onclick="openSessionHistory('${s.id}')">Ver</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">No hay sesiones guardadas con estos filtros.</div>'}`;
}
function openSessionHistory(id){
 const s=sessionHistory.find(x=>x.id===id);if(!s)return;
 let att={};try{att=JSON.parse(s.attendance_json||'{}')}catch{}
 const entries=Object.entries(att);
 const label=v=>({presente:'Presente',ausente:'Ausente',tarde:'Llegó tarde',excusado:'Excusado'}[v]||v||'Sin registrar');
 const rows=entries.map(([athleteId,value])=>{
  const e=typeof value==='string'?{status:value,note:''}:value||{};
  const p=state.athletes.find(x=>x.id===athleteId);
  return `<tr><td><strong>${esc(p?.name||'Deportista')}</strong></td><td><span class="badge ${e.status==='presente'?'ok':e.status==='ausente'?'danger':'warn'}">${esc(label(e.status))}</span></td><td>${e.note?esc(e.note):'<span class="muted">—</span>'}</td></tr>`;
 }).join('');
 const a=sessionAttendanceSummary(s);
 showModal('Entrenamiento · '+dateText(s.date),`<div class="detail-grid"><div class="detail"><small>Categoría</small>${esc(s.category)}</div><div class="detail"><small>Estado</small>${esc(sessionStatusLabel(s.status))}</div><div class="detail"><small>Asistencia</small>${s.attendance_saved?a.present+' presentes · '+a.absent+' ausentes':'Sin asistencia guardada'}</div><div class="detail"><small>Última actualización</small>${s.updated_at?new Date(s.updated_at).toLocaleString('es-CO',{timeZone:'America/Bogota'}):'—'}</div></div><div class="section-title">OBSERVACIONES</div><div class="detail">${s.notes?esc(s.notes):'<span class="muted">Sin observaciones.</span>'}</div><div class="section-title">ASISTENCIA</div>${rows?`<div class="table-wrap"><table><thead><tr><th>Deportista</th><th>Estado</th><th>Nota</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="empty">No hay asistencia guardada.</div>'}`);
}
function moveWeek(n){weekStart=isoAdd(weekStart,n);render()}
async function chooseSession(key){chosenSession=currentSchedule().find(s=>s.key===key);if(!chosenSession)return;sessionData=null;go('asistencia');await loadSession()}
function attendancePage(){if(!chosenSession)return title('ASISTENCIA','Elige el entrenamiento.','Cada fecha y categoría tiene su propia lista.')+`<section class="card"><div class="card-head"><h2>Sesiones de esta semana</h2><button class="btn link" onclick="go('sesiones')">Cambiar semana</button></div>${currentSchedule().map(s=>`<div class="info-row"><div><strong>${WEEKDAYS[s.day]} ${dateText(s.date)} · ${s.category}</strong><small>${s.start}–${s.end} · ${CLUB.venues[s.venue]}</small></div><button class="btn link" onclick="chooseSession('${s.key}')">Elegir</button></div>`).join('')}</section>`;
 const s=chosenSession;return title('ASISTENCIA Y EJECUCIÓN','Categoría '+s.category,WEEKDAYS[s.day]+' '+dateText(s.date)+' · '+s.start+'–'+s.end,button('Otra sesión',"chosenSession=null;sessionData=null;go('asistencia')"))+`<p class="sub" style="margin-bottom:18px">${CLUB.venues[s.venue]} · ${s.coaches.map(id=>coachById(id).name).join(' · ')}</p><div id="session-content">${sessionData?sessionBody():'Cargando la sesión…'}</div>`;}
async function loadSession(){const key=chosenSession?.key;if(!key)return;try{const d=await api('sessions/'+encodeURIComponent(key));if(chosenSession?.key!==key)return;sessionData=d.session;if(view==='asistencia'){document.querySelector('#session-content').innerHTML=sessionBody();setTimeout(updateAttendanceSummary,0)}}catch(err){const el=document.querySelector('#session-content');if(el)el.innerHTML=errorBox(err.message)+button('Reintentar','loadSession()')}}
function attendanceEntry(att,id){const e=att[id];return typeof e==='string'?{status:e,note:''}:{status:e?.status||'',note:e?.note||''}}
function sessionBody(){const ps=state.athletes.filter(p=>p.category===chosenSession.category&&p.status==='active'),att=JSON.parse(sessionData.attendance_json||'{}');return `<section class="card"><div class="card-head"><div><h2>Lista de deportistas</h2><p>${sessionData.attendance_saved?'Último guardado: '+new Date(sessionData.updated_at).toLocaleString('es-CO',{timeZone:'America/Bogota'}):'Sin asistencia guardada'}</p></div><span class="badge blue">${ps.length} deportistas</span></div>${ps.length?`<div class="form-actions" style="justify-content:flex-start;padding:0 20px 14px;gap:8px;flex-wrap:wrap"><button type="button" class="btn primary" onclick="markAllAttendance('presente')">Todos presentes</button><button type="button" class="btn" onclick="clearAllAttendance()">Limpiar</button></div><div id="attendance-summary" class="stats" style="padding:0 20px 14px"></div>${ps.map(p=>{const entry=attendanceEntry(att,p.id);const status=['presente','ausente'].includes(entry.status)?entry.status:'';return `<div class="attendance-row" data-player-row="${p.id}" data-status="${status}">${person(p)}${eligibilityBadge(p)}<div class="attendance-controls attendance-controls-simple"><div class="attendance-markers" role="group" aria-label="Asistencia de ${esc(p.name)}"><button type="button" class="attendance-marker present ${status==='presente'?'active':''}" data-status="presente" aria-pressed="${status==='presente'}" onclick="setAttendanceStatus('${p.id}','presente')">✓ <span>Presente</span></button><button type="button" class="attendance-marker absent ${status==='ausente'?'active':''}" data-status="ausente" aria-pressed="${status==='ausente'}" onclick="setAttendanceStatus('${p.id}','ausente')">× <span>Ausente</span></button></div><input class="attendance-note" data-player="${p.id}" value="${esc(entry.note)}" maxlength="250" placeholder="Nota (opcional)" aria-label="Nota sobre ${esc(p.name)}"></div></div>`}).join('')}`:'<div class="empty">Aún no hay deportistas registrados en esta categoría.</div>'}<div id="attendance-error" style="padding:0 20px"></div>${ps.length?'<div class="attendance-footer"><span>Marca cada jugador como presente o ausente antes de guardar.</span><button class="btn primary" id="save-attendance" onclick="saveAttendance()">Guardar asistencia</button></div>':''}</section><section class="card"><div class="card-head"><h2>Ejecución de la sesión</h2></div><div class="training-inner"><div class="form-grid"><label class="field">Estado<select id="session-status">${[['programada','Programada'],['realizada','Realizada'],['cancelada','Cancelada']].map(([v,t])=>`<option value="${v}" ${sessionData.status===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="field full">Observaciones<textarea id="session-notes" maxlength="3000" rows="3">${esc(sessionData.notes)}</textarea></label></div><div id="execution-error"></div><div class="form-actions"><button class="btn primary" id="save-execution" onclick="saveExecution()">Guardar ejecución</button></div></div></section>`}
async function saveAttendance(){const btn=document.querySelector('#save-attendance');if(btn.disabled)return;const att={};document.querySelectorAll('[data-player-row]').forEach(row=>{const id=row.dataset.playerRow,note=document.querySelector('.attendance-note[data-player="'+id+'"]')?.value.trim()||'';att[id]={status:row.dataset.status||'',note}});if(Object.values(att).some(v=>!v.status))return toast('Marca todos los jugadores como presentes o ausentes antes de guardar.');btn.disabled=true;try{const r=await api('sessions/'+encodeURIComponent(chosenSession.key),'PUT',{operation:'attendance',version:sessionData.version,attendance:att});sessionData.version=r.version;sessionData.attendance_json=JSON.stringify(att);sessionData.attendance_saved=1;sessionData.updated_at=new Date().toISOString();document.querySelector('#attendance-error').innerHTML='<p class="saved-note">Asistencia guardada en la base del club.</p>';toast('Asistencia guardada. Puedes cerrar la aplicación.')}catch(e){document.querySelector('#attendance-error').innerHTML=errorBox(e.message)+(e.message.includes('Recarga')||e.message.includes('recarga')?button('Recargar lista guardada','loadSession()'):'')}finally{btn.disabled=false}}
async function saveExecution(){const btn=document.querySelector('#save-execution');if(btn.disabled)return;btn.disabled=true;const notes=document.querySelector('#session-notes').value,status=document.querySelector('#session-status').value;try{const r=await api('sessions/'+encodeURIComponent(chosenSession.key),'PUT',{operation:'execution',version:sessionData.version,notes,status});sessionData.version=r.version;sessionData.notes=notes;sessionData.status=status;toast('Ejecución guardada en la base del club.');chosenSession=null;sessionData=null;go('asistencia')}catch(e){document.querySelector('#execution-error').innerHTML=errorBox(e.message)+button('Recargar sesión','loadSession()')}finally{btn.disabled=false}}
function team(){return title('ORGANIZACIÓN','Equipo y categorías.','Horarios configurados para el club.')+(admin()?`<div class="admin-grid">${state.staff.filter(s=>s.role==='admin').map(s=>`<article class="admin-card"><span class="avatar">${initials(s.name)}</span><div><small>${esc(s.title)}</small><h3>${esc(s.name)}</h3></div></article>`).join('')}</div>`:'')+`<section class="card"><div class="card-head"><h2>Horarios por categoría</h2></div><div class="category-grid">${state.categories.map(c=>`<article class="category-card"><h3>${c}</h3>${state.schedule.filter(s=>s.category===c).sort((a,b)=>a.day-b.day).map(s=>`<div class="category-line"><b>${WEEKDAYS[s.day]} · ${s.start}–${s.end}</b><span>${CLUB.venues[s.venue]}</span><small>${s.coaches.map(id=>coachById(id).name).join(' · ')}</small></div>`).join('')}</article>`).join('')}</div></section>`}
function accountPage(){return title('MI CUENTA','Cuenta personal.','Consulta tus pagos del club y administra la seguridad de tu acceso.')+`<section class="card"><div class="card-head"><div><h2>Mi fotografía</h2><p>Se mostrará en tu pantalla de inicio y en el menú lateral.</p></div></div><div class="training-inner staff-photo-editor">${staffAvatar(true)}<div><strong>${esc(state.member.name)}</strong><p class="muted">JPG, PNG o WebP · máximo 2 MB. Solo puedes cambiar tu fotografía.</p><label class="btn staff-photo-upload">Subir o cambiar fotografía<input type="file" accept="image/jpeg,image/png,image/webp" onchange="saveStaffPhoto(this)" hidden></label><button class="btn" type="button" onclick="openStaffCamera()">Tomar foto con cámara</button><div id="staff-camera-panel" class="staff-camera-panel" hidden><video id="staff-camera-video" autoplay muted playsinline></video><div class="staff-camera-actions"><button class="btn primary" type="button" onclick="captureStaffCamera()">Capturar y guardar foto</button><button class="btn" type="button" onclick="closeStaffCamera()">Cancelar</button></div></div></div></div></section>`+`<div id="my-coach-payments"></div><section class="card"><div class="card-head"><div><h2>Seguridad de acceso</h2><p>${esc(state.member.name)} · ${esc(state.member.title)}</p></div></div><div class="training-inner"><form id="account-password-form"><div class="form-grid"><label class="field full">Contraseña actual<span class="password-field"><input name="currentPassword" type="password" autocomplete="current-password" required maxlength="128"><button type="button" class="password-toggle" aria-label="Mostrar contraseña" onclick="togglePasswordInput(this)">${icon('eye')}</button></span></label><label class="field full">Nueva contraseña<span class="password-field"><input name="newPassword" type="password" autocomplete="new-password" required maxlength="128"><button type="button" class="password-toggle" aria-label="Mostrar contraseña" onclick="togglePasswordInput(this)">${icon('eye')}</button></span></label><label class="field full">Confirmar nueva contraseña<span class="password-field"><input name="confirmPassword" type="password" autocomplete="new-password" required maxlength="128"><button type="button" class="password-toggle" aria-label="Mostrar contraseña" onclick="togglePasswordInput(this)">${icon('eye')}</button></span></label></div><p class="muted" style="margin-top:16px">Mínimo 10 caracteres, con al menos una letra y un número. Al cambiarla, se cerrará la sesión y deberás ingresar nuevamente.</p><div id="account-password-error"></div><div class="form-actions"><button class="btn primary" type="submit">Cambiar contraseña</button></div></form></div></section>`}
function bindAccountForm(){if(typeof loadMyCoachPayments==='function')loadMyCoachPayments();const form=document.querySelector('#account-password-form');if(!form)return;form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;const d=Object.fromEntries(new FormData(form));try{await api('account/password','PUT',d);window.location.href='/auth/logout'}catch(err){document.querySelector('#account-password-error').innerHTML=errorBox(err.message);submit.disabled=false}}}
function accessPage(){if(!state.member.owner)return errorBox('Acceso restringido.');return title('ACCESOS','Usuarios del club.','Crea un usuario y una contraseña para cada persona autorizada.')+`<div class="notice neutral">Los usuarios ingresan directamente a la aplicación. Desde aquí puedes activar, bloquear o restablecer la contraseña de cada cuenta.</div><section class="card"><div class="card-head"><div><h2>Correo del club</h2><p>${esc(state.clubEmail)} · Uso institucional</p></div></div></section><section class="card"><div class="table-wrap"><table><thead><tr><th>Persona</th><th>Función</th><th>Usuario</th><th>Correo</th><th>Estado</th><th>Configurar</th></tr></thead><tbody>${state.staff.map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td>${esc(s.title)}</td><td>${esc(s.username||'Sin usuario')}</td><td>${esc(s.email||'Por registrar')}</td><td><span class="badge ${!s.active?'danger':s.username&&s.has_password?'ok':'warn'}">${!s.active?'Desactivado':s.username&&s.has_password?'Listo para ingresar':'Configuración pendiente'}</span></td><td>${s.owner?'<span class="muted">Responsable inicial</span>':`<div class="access-actions"><button class="access-action-btn" onclick="staffForm('${s.id}')">Editar</button><button class="access-action-btn secondary" onclick="resetStaffPassword('${s.id}')">Contraseña</button></div>`}</td></tr>`).join('')}</tbody></table></div></section>`}
function staffForm(id){const s=state.staff.find(s=>s.id===id);if(!s||s.owner||!state.member.owner)return;showModal('Configurar usuario',`<p class="sub" style="margin-bottom:18px">${esc(s.title)} · La contraseña nunca se mostrará después de guardarla.</p><form id="staff-form"><div class="form-grid">${field('Nombre','name',s.name,'text',true,true,100)}${field('Usuario','username',s.username||'','text',true,false,40)}${field('Correo (opcional)','email',s.email,'email',false,true,254)}<label class="field full">Contraseña ${s.has_password?'(dejar vacía para conservarla)':'inicial'}<span class="password-field"><input name="password" type="password" autocomplete="new-password" maxlength="128" ${s.has_password?'':'required'} placeholder="${s.has_password?'Solo escribe una nueva si deseas restablecerla':'Mínimo 10 caracteres, letra y número'}"><button type="button" class="password-toggle" aria-label="Mostrar contraseña" onclick="togglePasswordInput(this)">${icon('eye')}</button></span></label><label class="field full consent-check"><input type="checkbox" name="active" ${s.active?'checked':''}>Usuario activo</label></div><p class="muted" style="margin-top:16px">Usuario: letras, números, punto, guion o guion bajo. La contraseña debe tener mínimo 10 caracteres, una letra y un número.</p><div id="form-error"></div><div class="form-actions"><button type="button" class="btn" onclick="modal.close()">Cancelar</button><button class="btn primary">Guardar acceso</button></div></form>`);document.querySelector('#staff-form').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('[type=submit]')||e.target.querySelector('.primary');if(submit.disabled)return;submit.disabled=true;const d=Object.fromEntries(new FormData(e.target));try{await api('staff/'+id,'PUT',{name:d.name,username:d.username,email:d.email,password:d.password||'',active:d.active==='on'});await refresh();modal.close();render();toast('Acceso actualizado.')}catch(e){document.querySelector('#form-error').innerHTML=errorBox(e.message);submit.disabled=false}}}
function resetStaffPassword(id){const s=state.staff.find(s=>s.id===id);if(!s||s.owner||!state.member.owner)return;showModal('Restablecer contraseña',`<p class="sub" style="margin-bottom:18px">${esc(s.name)} · ${esc(s.title)}</p><form id="reset-password-form"><label class="field full">Nueva contraseña<span class="password-field"><input name="password" type="password" autocomplete="new-password" required maxlength="128"><button type="button" class="password-toggle" aria-label="Mostrar contraseña" onclick="togglePasswordInput(this)">${icon('eye')}</button></span></label><p class="muted" style="margin-top:14px">Al guardar, las sesiones abiertas de esta persona se cerrarán automáticamente.</p><div id="form-error"></div><div class="form-actions"><button type="button" class="btn" onclick="modal.close()">Cancelar</button><button class="btn primary" type="submit">Restablecer contraseña</button></div></form>`);document.querySelector('#reset-password-form').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('[type=submit]');submit.disabled=true;const d=Object.fromEntries(new FormData(e.target));try{await api('staff/'+id,'PUT',{name:s.name,username:s.username,email:s.email||'',password:d.password,active:!!s.active});await refresh();modal.close();render();toast('Contraseña restablecida.')}catch(err){document.querySelector('#form-error').innerHTML=errorBox(err.message);submit.disabled=false}}}
function auditPage(){setTimeout(loadAudit,0);return title('ACTIVIDAD','Cambios registrados.','Últimas 30 operaciones guardadas en la base del club.')+'<section class="card" id="audit-list"><div class="empty">Cargando actividad…</div></section>'}
async function loadAudit(){try{const r=await api('audit');const el=document.querySelector('#audit-list');if(!el)return;const actions={athlete_created:'Ficha creada',athlete_preregistered:'Prerregistro creado',athlete_completed:'Ficha completada',athlete_updated:'Ficha actualizada',measurement_created:'Medición registrada',attendance_saved:'Asistencia guardada',session_updated:'Ejecución actualizada',staff_access_updated:'Permiso actualizado',password_changed:'Contraseña cambiada',password_changed_first_login:'Contraseña inicial reemplazada',password_reset_admin:'Contraseña restablecida por administrador',login_success:'Inicio de sesión correcto',athlete_photo_updated:'Foto actualizada',athlete_photo_deleted:'Foto eliminada',receipt_emailed:'Comprobante enviado por correo'};el.innerHTML=r.events.length?`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Persona</th><th>Acción</th></tr></thead><tbody>${r.events.map(e=>`<tr><td>${new Date(e.created_at).toLocaleString('es-CO',{timeZone:'America/Bogota'})}</td><td>${esc(e.actor_name)}</td><td>${actions[e.action]||esc(e.action)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Aún no hay operaciones registradas.</div>'}catch(e){const el=document.querySelector('#audit-list');if(el)el.innerHTML=errorBox(e.message)}}
document.querySelector('#menu').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');document.querySelector('.brand').onclick=e=>{e.preventDefault();go('inicio')};modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
async function start(){try{await refresh();const allowed=['inicio','deportistas','asistencia','sesiones','equipo','cuenta','accesos','finanzas','contabilidad','historial'];if(!allowed.includes(view))view='inicio';if(!location.hash)history.replaceState(null,'','#'+view);render()}catch(e){main.innerHTML=errorBox(e.message)+button('Reintentar','start()',true)}}window.addEventListener('hashchange',()=>{const v=(location.hash||'#inicio').slice(1);if(v!==view){view=v;selectedCategory='Todas';selectedStatus='Todos';query='';render()}});start();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'open_club_view',description:'Abre una pantalla del club. No modifica registros.',inputSchema:{type:'object',properties:{view:{type:'string',enum:['inicio','deportistas','asistencia','sesiones','equipo']}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!state)throw Error('La cuenta aún no ha cargado');if(!input||!['inicio','deportistas','asistencia','sesiones','equipo'].includes(input.view))throw Error('Pantalla inválida');go(input.view);return {view,role:state.member.role}}})}catch{}}

function athleteNoteForm(id){
 const p=state.athletes.find(x=>x.id===id);if(!p)return;
 showModal('Nota interna · '+esc(p.name),`
  <p class="sub" style="margin-bottom:16px">Visible únicamente para personal autorizado del club. Úsala para observaciones operativas breves.</p>
  <form id="athlete-note-form">
   <label class="field full">Nota interna<textarea name="note" rows="5" maxlength="700" placeholder="Ej. Pendiente documento, uniforme por entregar, cambio temporal de horario…">${esc(p.internal_note||'')}</textarea></label>
   <p class="muted" style="margin-top:10px">Evita registrar aquí información médica sensible; para eso ya existe el campo correspondiente en la ficha.</p>
   <div id="athlete-note-error"></div>
   <div class="form-actions"><button type="button" class="btn" onclick="modal.close();profile('${id}')">Cancelar</button>${p.internal_note?'<button type="button" class="btn danger" onclick="clearAthleteNote(\''+id+'\')">Eliminar nota</button>':''}<button class="btn primary" type="submit">Guardar nota</button></div>
  </form>`);
 document.querySelector('#athlete-note-form').onsubmit=async e=>{
  e.preventDefault();const form=e.target,btn=form.querySelector('[type=submit]');btn.disabled=true;
  const d=Object.fromEntries(new FormData(form));
  try{await api('athletes/'+id+'/note','PUT',{note:d.note||''});await refresh();modal.close();profile(id);toast('Nota interna guardada.')}
  catch(err){document.querySelector('#athlete-note-error').innerHTML=errorBox(err.message);btn.disabled=false}
 };
}
async function clearAthleteNote(id){
 if(!confirm('¿Eliminar la nota interna de este deportista?'))return;
 try{await api('athletes/'+id+'/note','PUT',{note:''});await refresh();modal.close();profile(id);toast('Nota interna eliminada.')}
 catch(e){toast(e.message)}
}

function updateAttendanceSummary(){
 const el=document.querySelector('#attendance-summary');if(!el)return;
 const values=[...document.querySelectorAll('[data-player-row]')].map(x=>x.dataset.status||'');
 const count=s=>values.filter(v=>v===s).length;
 el.innerHTML=
  stat('Presentes',count('presente'),'Marcados presentes','check')+
  stat('Ausentes',count('ausente'),'Marcados ausentes','users')+
  stat('Sin registrar',count(''),'Pendientes','clock');
}
function paintAttendanceRow(row){
 const status=row.dataset.status||'';
 row.querySelectorAll('.attendance-marker').forEach(btn=>{
  const active=btn.dataset.status===status;
  btn.classList.toggle('active',active);
  btn.setAttribute('aria-pressed',active?'true':'false');
 });
}
function setAttendanceStatus(id,status){
 const row=document.querySelector('[data-player-row="'+id+'"]');if(!row)return;
 row.dataset.status=row.dataset.status===status?'':status;
 paintAttendanceRow(row);
 updateAttendanceSummary();
}
function markAllAttendance(status){
 document.querySelectorAll('[data-player-row]').forEach(row=>{row.dataset.status=status;paintAttendanceRow(row)});
 updateAttendanceSummary();
}
function clearAllAttendance(){
 document.querySelectorAll('[data-player-row]').forEach(row=>{row.dataset.status='';paintAttendanceRow(row)});
 updateAttendanceSummary();
}
